{
  "id": "beer-distribution-game-cla",
  "name": "Beer Distribution Game",
  "description": "The classic 'Beer Game' supply chain simulation developed at MIT Sloan. Demonstrates the bullwhip effect where small changes in retail demand cause increasingly larger fluctuations at each upstream stage (retailer, wholesaler, distributor, factory). Reference: Based on System Dynamics supply chain models (Sterman, 2000). Source: https://systemdynamics.org/",
  "stocks": [
    {
      "id": "stock-retailer-inventory",
      "name": "Retailer Inventory",
      "initial_value": 12,
      "equation": "",
      "position": {
        "x": 150,
        "y": 200
      }
    },
    {
      "id": "stock-wholesaler-inventory",
      "name": "Wholesaler Inventory",
      "initial_value": 12,
      "equation": "",
      "position": {
        "x": 350,
        "y": 200
      }
    },
    {
      "id": "stock-distributor-inventory",
      "name": "Distributor Inventory",
      "initial_value": 12,
      "equation": "",
      "position": {
        "x": 550,
        "y": 200
      }
    },
    {
      "id": "stock-factory-inventory",
      "name": "Factory Inventory",
      "initial_value": 12,
      "equation": "",
      "position": {
        "x": 750,
        "y": 200
      }
    },
    {
      "id": "stock-retailer-backlog",
      "name": "Retailer Backlog",
      "initial_value": 0,
      "equation": "",
      "position": {
        "x": 150,
        "y": 350
      }
    },
    {
      "id": "stock-supply-line-retailer",
      "name": "Supply Line Retailer",
      "initial_value": 8,
      "equation": "",
      "position": {
        "x": 350,
        "y": 350
      }
    },
    {
      "id": "stock-supply-line-wholesaler",
      "name": "Supply Line Wholesaler",
      "initial_value": 8,
      "equation": "",
      "position": {
        "x": 550,
        "y": 350
      }
    },
    {
      "id": "stock-supply-line-distributor",
      "name": "Supply Line Distributor",
      "initial_value": 8,
      "equation": "",
      "position": {
        "x": 750,
        "y": 350
      }
    }
  ],
  "flows": [
    {
      "id": "flow-customer-demand",
      "name": "Customer Demand",
      "equation": "IF Time < 5 THEN 4 ELSE 8",
      "from_stock": null,
      "to_stock": null,
      "position": {
        "x": 250,
        "y": 200
      }
    },
    {
      "id": "flow-retailer-orders",
      "name": "Retailer Orders",
      "equation": "MAX(0, Expected_Demand + Inventory_Adjustment_Retailer + Supply_Line_Adjustment_Retailer)",
      "from_stock": null,
      "to_stock": "stock-supply-line-retailer",
      "position": {
        "x": 450,
        "y": 200
      }
    },
    {
      "id": "flow-wholesaler-orders",
      "name": "Wholesaler Orders",
      "equation": "MAX(0, Retailer_Orders + Inventory_Adjustment_Wholesaler + Supply_Line_Adjustment_Wholesaler)",
      "from_stock": null,
      "to_stock": "stock-supply-line-wholesaler",
      "position": {
        "x": 650,
        "y": 200
      }
    },
    {
      "id": "flow-distributor-orders",
      "name": "Distributor Orders",
      "equation": "MAX(0, Wholesaler_Orders + Inventory_Adjustment_Distributor + Supply_Line_Adjustment_Distributor)",
      "from_stock": null,
      "to_stock": "stock-supply-line-distributor",
      "position": {
        "x": 250,
        "y": 350
      }
    },
    {
      "id": "flow-production",
      "name": "Production",
      "equation": "DELAY3(Production_Order, Production_Delay)",
      "from_stock": null,
      "to_stock": "stock-factory-inventory",
      "position": {
        "x": 450,
        "y": 350
      }
    }
  ],
  "variables": [
    {
      "id": "var-shipping-delay",
      "name": "Shipping Delay",
      "equation": "2",
      "position": {
        "x": 100,
        "y": 80
      }
    },
    {
      "id": "var-production-delay",
      "name": "Production Delay",
      "equation": "3",
      "position": {
        "x": 250,
        "y": 80
      }
    },
    {
      "id": "var-desired-inventory",
      "name": "Desired Inventory",
      "equation": "12",
      "position": {
        "x": 400,
        "y": 80
      }
    },
    {
      "id": "var-inventory-adjustment-time",
      "name": "Inventory Adjustment Time",
      "equation": "4",
      "position": {
        "x": 550,
        "y": 80
      }
    },
    {
      "id": "var-expected-demand",
      "name": "Expected Demand",
      "equation": "SMOOTH(Customer_Demand, Demand_Forecast_Time)",
      "position": {
        "x": 700,
        "y": 80
      }
    },
    {
      "id": "var-demand-forecast-time",
      "name": "Demand Forecast Time",
      "equation": "4",
      "position": {
        "x": 100,
        "y": 160
      }
    }
  ],
  "connectors": [
    {
      "id": "conn-1",
      "from_element": "Customer Demand",
      "to_element": "retailer_shipments"
    },
    {
      "id": "conn-2",
      "from_element": "Retailer Orders",
      "to_element": "Supply Line Retailer"
    },
    {
      "id": "conn-3",
      "from_element": "Wholesaler Orders",
      "to_element": "Supply Line Wholesaler"
    },
    {
      "id": "conn-4",
      "from_element": "Distributor Orders",
      "to_element": "Supply Line Distributor"
    }
  ],
  "time_settings": {
    "start": 0,
    "end": 52,
    "dt": 1
  },
  "created_at": "2026-01-11T20:04:50.689151Z",
  "updated_at": "2026-01-11T20:04:50.689151Z",
  "source": "https://doi.org/10.1287/mnsc.35.3.321",
  "reference": "Sterman JD. Business Dynamics: Systems Thinking and Modeling for a Complex World. McGraw-Hill, 2000."
}

{
  "id": "world2-forrester-original-cla",
  "name": "World2 Forrester Original Model",
  "description": "Jay Forrester's original WORLD2 model from 1971. A five-sector global model examining interactions between population, capital investment, natural resources, pollution, and quality of life. Reference: Forrester, J. W. (1961). Industrial Dynamics. MIT Press. Source: https://systemdynamics.org/",
  "source": "https://mitpress.mit.edu/9780262560047/world-dynamics/",
  "reference": "Forrester, J.W. (1971). World Dynamics. Wright-Allen Press/MIT Press. Cambridge, MA.",
  "stocks": [
    {
      "id": "stock-pop",
      "name": "Population",
      "initial_value": 1650000000,
      "equation": "",
      "position": {
        "x": 100,
        "y": 200
      }
    },
    {
      "id": "stock-capital",
      "name": "Capital Investment",
      "initial_value": 400000000,
      "equation": "",
      "position": {
        "x": 300,
        "y": 200
      }
    },
    {
      "id": "stock-resources",
      "name": "Natural Resources",
      "initial_value": 900000000000,
      "equation": "",
      "position": {
        "x": 500,
        "y": 200
      }
    },
    {
      "id": "stock-pollution",
      "name": "Pollution",
      "initial_value": 200000000,
      "equation": "",
      "position": {
        "x": 300,
        "y": 350
      }
    },
    {
      "id": "stock-agric-frac",
      "name": "Capital in Agriculture Fraction",
      "initial_value": 0.2,
      "equation": "",
      "position": {
        "x": 100,
        "y": 350
      }
    }
  ],
  "flows": [
    {
      "id": "flow-births",
      "name": "Birth Rate",
      "equation": "Population * Birth_Rate_Normal * Birth_Rate_Multiplier",
      "from_stock": null,
      "to_stock": "stock-pop",
      "position": {
        "x": 50,
        "y": 200
      }
    },
    {
      "id": "flow-deaths",
      "name": "Death Rate",
      "equation": "Population * Death_Rate_Normal * Death_Rate_Multiplier",
      "from_stock": "stock-pop",
      "to_stock": null,
      "position": {
        "x": 150,
        "y": 200
      }
    },
    {
      "id": "flow-capital-gen",
      "name": "Capital Generation",
      "equation": "Population * Capital_Generation_Normal * Capital_Generation_Multiplier",
      "from_stock": null,
      "to_stock": "stock-capital",
      "position": {
        "x": 250,
        "y": 200
      }
    },
    {
      "id": "flow-depreciation",
      "name": "Capital Depreciation",
      "equation": "Capital_Investment / Capital_Normal_Lifetime",
      "from_stock": "stock-capital",
      "to_stock": null,
      "position": {
        "x": 350,
        "y": 200
      }
    },
    {
      "id": "flow-resource-use",
      "name": "Resource Usage",
      "equation": "Population * Resource_Usage_Normal * Resource_Usage_Multiplier",
      "from_stock": "stock-resources",
      "to_stock": null,
      "position": {
        "x": 500,
        "y": 250
      }
    },
    {
      "id": "flow-pollution-gen",
      "name": "Pollution Generation",
      "equation": "Population * Pollution_Normal * Pollution_Generation_Multiplier",
      "from_stock": null,
      "to_stock": "stock-pollution",
      "position": {
        "x": 250,
        "y": 350
      }
    },
    {
      "id": "flow-pollution-absorb",
      "name": "Pollution Absorption",
      "equation": "Pollution / Pollution_Absorption_Time",
      "from_stock": "stock-pollution",
      "to_stock": null,
      "position": {
        "x": 350,
        "y": 350
      }
    },
    {
      "id": "flow-agric-adjust",
      "name": "Agriculture Adjustment",
      "equation": "(Desired_Agric_Fraction - Capital_in_Agriculture_Fraction) / Agric_Adjustment_Time",
      "from_stock": null,
      "to_stock": "stock-agric-frac",
      "position": {
        "x": 100,
        "y": 400
      }
    }
  ],
  "variables": [
    {
      "id": "var-brn",
      "name": "Birth Rate Normal",
      "equation": "0.04",
      "position": {
        "x": 50,
        "y": 150
      }
    },
    {
      "id": "var-brm",
      "name": "Birth Rate Multiplier",
      "equation": "BRM_Material * BRM_Crowding * BRM_Food * BRM_Pollution",
      "position": {
        "x": 100,
        "y": 100
      }
    },
    {
      "id": "var-brm-mat",
      "name": "BRM Material",
      "equation": "1.2 - 0.8 * Material_Standard_of_Living / 5",
      "position": {
        "x": 50,
        "y": 50
      }
    },
    {
      "id": "var-brm-crowd",
      "name": "BRM Crowding",
      "equation": "1 - 0.5 * Crowding_Ratio",
      "position": {
        "x": 150,
        "y": 50
      }
    },
    {
      "id": "var-brm-food",
      "name": "BRM Food",
      "equation": "1 + 0.2 * (Food_Ratio - 1)",
      "position": {
        "x": 250,
        "y": 50
      }
    },
    {
      "id": "var-brm-poll",
      "name": "BRM Pollution",
      "equation": "1 - 0.3 * Pollution_Ratio",
      "position": {
        "x": 350,
        "y": 50
      }
    },
    {
      "id": "var-drn",
      "name": "Death Rate Normal",
      "equation": "0.028",
      "position": {
        "x": 150,
        "y": 150
      }
    },
    {
      "id": "var-drm",
      "name": "Death Rate Multiplier",
      "equation": "DRM_Material * DRM_Crowding * DRM_Food * DRM_Pollution",
      "position": {
        "x": 200,
        "y": 100
      }
    },
    {
      "id": "var-drm-mat",
      "name": "DRM Material",
      "equation": "0.6 + 0.4 / (Material_Standard_of_Living + 0.1)",
      "position": {
        "x": 50,
        "y": 250
      }
    },
    {
      "id": "var-drm-crowd",
      "name": "DRM Crowding",
      "equation": "1 + 0.5 * Crowding_Ratio",
      "position": {
        "x": 150,
        "y": 250
      }
    },
    {
      "id": "var-drm-food",
      "name": "DRM Food",
      "equation": "1 / (Food_Ratio + 0.1)",
      "position": {
        "x": 250,
        "y": 250
      }
    },
    {
      "id": "var-drm-poll",
      "name": "DRM Pollution",
      "equation": "1 + 0.5 * Pollution_Ratio",
      "position": {
        "x": 350,
        "y": 250
      }
    },
    {
      "id": "var-cgn",
      "name": "Capital Generation Normal",
      "equation": "0.05",
      "position": {
        "x": 250,
        "y": 150
      }
    },
    {
      "id": "var-cgm",
      "name": "Capital Generation Multiplier",
      "equation": "1",
      "position": {
        "x": 300,
        "y": 100
      }
    },
    {
      "id": "var-cnl",
      "name": "Capital Normal Lifetime",
      "equation": "40",
      "position": {
        "x": 350,
        "y": 150
      }
    },
    {
      "id": "var-run",
      "name": "Resource Usage Normal",
      "equation": "1",
      "position": {
        "x": 450,
        "y": 150
      }
    },
    {
      "id": "var-rum",
      "name": "Resource Usage Multiplier",
      "equation": "Material_Standard_of_Living",
      "position": {
        "x": 500,
        "y": 100
      }
    },
    {
      "id": "var-pn",
      "name": "Pollution Normal",
      "equation": "1",
      "position": {
        "x": 250,
        "y": 300
      }
    },
    {
      "id": "var-pgm",
      "name": "Pollution Generation Multiplier",
      "equation": "Material_Standard_of_Living",
      "position": {
        "x": 300,
        "y": 250
      }
    },
    {
      "id": "var-pat",
      "name": "Pollution Absorption Time",
      "equation": "100",
      "position": {
        "x": 350,
        "y": 300
      }
    },
    {
      "id": "var-msol",
      "name": "Material Standard of Living",
      "equation": "Capital_Investment / Population / 0.2",
      "position": {
        "x": 400,
        "y": 100
      }
    },
    {
      "id": "var-food-ratio",
      "name": "Food Ratio",
      "equation": "Capital_Investment * Capital_in_Agriculture_Fraction / Population / 0.1",
      "position": {
        "x": 200,
        "y": 400
      }
    },
    {
      "id": "var-crowd",
      "name": "Crowding Ratio",
      "equation": "Population / 3700000000",
      "position": {
        "x": 100,
        "y": 150
      }
    },
    {
      "id": "var-poll-ratio",
      "name": "Pollution Ratio",
      "equation": "Pollution / 350000000",
      "position": {
        "x": 400,
        "y": 350
      }
    },
    {
      "id": "var-res-ratio",
      "name": "Resource Ratio",
      "equation": "Natural_Resources / 900000000000",
      "position": {
        "x": 550,
        "y": 150
      }
    },
    {
      "id": "var-qol",
      "name": "Quality of Life",
      "equation": "(Material_Standard_of_Living * Food_Ratio) / ((Crowding_Ratio + 0.1) * (Pollution_Ratio + 0.1))",
      "position": {
        "x": 450,
        "y": 350
      }
    },
    {
      "id": "var-desired-agric",
      "name": "Desired Agric Fraction",
      "equation": "0.3 - 0.1 * Food_Ratio",
      "position": {
        "x": 50,
        "y": 400
      }
    },
    {
      "id": "var-agric-adj-time",
      "name": "Agric Adjustment Time",
      "equation": "15",
      "position": {
        "x": 150,
        "y": 400
      }
    }
  ],
  "connectors": [],
  "time_settings": {
    "start": 1900,
    "end": 2100,
    "dt": 1
  },
  "created_at": "2026-01-12T03:11:09.889436+00:00",
  "updated_at": "2026-01-12T03:11:09.889436+00:00"
}

{
  "id": "world3-non-renewable-resources-sector-cla",
  "name": "World3 Non-Renewable Resources Sector",
  "description": "The non-renewable resource dynamics sector from the World3 model. Models resource extraction, depletion, and the effect of declining resource availability on the economy. Reference: IRENA Renewable Energy Statistics. Source: https://www.irena.org/",
  "stocks": [
    {
      "id": "stock-non-renewable-resources",
      "name": "Non-Renewable Resources",
      "initial_value": 1000000000000.0,
      "equation": "",
      "position": {
        "x": 150,
        "y": 200
      }
    }
  ],
  "flows": [
    {
      "id": "flow-resource-usage-rate",
      "name": "Resource Usage Rate",
      "equation": "Population * Per_Capita_Resource_Usage * Resource_Usage_Multiplier",
      "from_stock": "stock-non-renewable-resources",
      "to_stock": null,
      "position": {
        "x": 250,
        "y": 200
      }
    }
  ],
  "variables": [
    {
      "id": "var-population",
      "name": "Population",
      "equation": "3e9",
      "position": {
        "x": 100,
        "y": 80
      }
    },
    {
      "id": "var-per-capita-resource-usage",
      "name": "Per Capita Resource Usage",
      "equation": "1",
      "position": {
        "x": 250,
        "y": 80
      }
    },
    {
      "id": "var-resource-usage-multiplier",
      "name": "Resource Usage Multiplier",
      "equation": "Resource_Usage_From_Industry(Industrial_Output_Per_Capita)",
      "position": {
        "x": 400,
        "y": 80
      }
    },
    {
      "id": "var-fraction-of-resources-remaining",
      "name": "Fraction of Resources Remaining",
      "equation": "\"Non-Renewable Resources\" / Initial_Resources",
      "position": {
        "x": 550,
        "y": 80
      }
    },
    {
      "id": "var-initial-resources",
      "name": "Initial Resources",
      "equation": "1e12",
      "position": {
        "x": 700,
        "y": 80
      }
    },
    {
      "id": "var-resource-extraction-capital-requirement",
      "name": "Resource Extraction Capital Requirement",
      "equation": "Resource_Extraction_Fraction(Fraction_of_Resources_Remaining)",
      "position": {
        "x": 100,
        "y": 160
      }
    }
  ],
  "connectors": [],
  "time_settings": {
    "start": 1900,
    "end": 2100,
    "dt": 1
  },
  "created_at": "2026-01-11T20:04:50.697230Z",
  "updated_at": "2026-01-11T20:04:50.697230Z",
  "source": "https://doi.org/10.1016/B978-0-12-850754-3.50020-2",
  "reference": "Meadows DH, Meadows DL, Randers J, Behrens WW. The Limits to Growth. Universe Books, 1972."
}

{
  "id": "agricultural-water-demand-cli",
  "name": "Agricultural Water Demand Model",
  "description": "A system dynamics model of agricultural water demand and irrigation. Models the interactions between crop production, water availability, irrigation efficiency, and the feedback effects of water stress on yield and farmer adaptation. Reference: FAO AQUASTAT. Water resources and agricultural water management. Source: https://www.fao.org/aquastat/",
  "stocks": [
    {
      "id": "stock-soil-moisture",
      "name": "Soil Moisture",
      "initial_value": 200,
      "equation": "",
      "position": {
        "x": 300,
        "y": 150
      }
    },
    {
      "id": "stock-crop-biomass",
      "name": "Crop Biomass",
      "initial_value": 100,
      "equation": "",
      "position": {
        "x": 300,
        "y": 300
      }
    },
    {
      "id": "stock-irrigation-capacity",
      "name": "Irrigation Capacity",
      "initial_value": 50,
      "equation": "",
      "position": {
        "x": 550,
        "y": 150
      }
    },
    {
      "id": "stock-water-reservoir",
      "name": "Water Reservoir",
      "initial_value": 1000,
      "equation": "",
      "position": {
        "x": 100,
        "y": 150
      }
    },
    {
      "id": "stock-farm-revenue",
      "name": "Cumulative Farm Revenue",
      "initial_value": 0,
      "equation": "",
      "position": {
        "x": 550,
        "y": 300
      }
    }
  ],
  "flows": [
    {
      "id": "flow-precipitation",
      "name": "Precipitation Input",
      "equation": "Base_Precipitation * (1 + 0.5 * SIN(TIME * 2 * 3.14159 / 12))",
      "from_stock": null,
      "to_stock": "stock-soil-moisture",
      "position": {
        "x": 200,
        "y": 100
      }
    },
    {
      "id": "flow-irrigation",
      "name": "Irrigation",
      "equation": "MIN(Irrigation_Demand, MIN(Irrigation_Capacity, Water_Reservoir / Time_Step))",
      "from_stock": "stock-water-reservoir",
      "to_stock": "stock-soil-moisture",
      "position": {
        "x": 200,
        "y": 150
      }
    },
    {
      "id": "flow-evapotranspiration",
      "name": "Evapotranspiration",
      "equation": "Potential_ET * MIN(1, Soil_Moisture / Field_Capacity) * Crop_Coefficient",
      "from_stock": "stock-soil-moisture",
      "to_stock": null,
      "position": {
        "x": 400,
        "y": 150
      }
    },
    {
      "id": "flow-deep-percolation",
      "name": "Deep Percolation",
      "equation": "MAX(0, Soil_Moisture - Field_Capacity) * Percolation_Rate",
      "from_stock": "stock-soil-moisture",
      "to_stock": null,
      "position": {
        "x": 300,
        "y": 50
      }
    },
    {
      "id": "flow-crop-growth",
      "name": "Crop Growth",
      "equation": "Potential_Growth * Water_Stress_Factor * Temperature_Factor",
      "from_stock": null,
      "to_stock": "stock-crop-biomass",
      "position": {
        "x": 200,
        "y": 300
      }
    },
    {
      "id": "flow-harvest",
      "name": "Harvest",
      "equation": "IF(MOD(TIME, 12) > 10, Crop_Biomass * Harvest_Fraction, 0)",
      "from_stock": "stock-crop-biomass",
      "to_stock": null,
      "position": {
        "x": 400,
        "y": 300
      }
    },
    {
      "id": "flow-capacity-investment",
      "name": "Capacity Investment",
      "equation": "Investment_Rate * Investment_Decision",
      "from_stock": null,
      "to_stock": "stock-irrigation-capacity",
      "position": {
        "x": 550,
        "y": 50
      }
    },
    {
      "id": "flow-capacity-depreciation",
      "name": "Capacity Depreciation",
