        "x": 100,
        "y": 80
      }
    },
    {
      "id": "var-peer-effect",
      "name": "Peer_Effect",
      "equation": "0.5",
      "position": {
        "x": 220,
        "y": 80
      }
    },
    {
      "id": "var-total-farms",
      "name": "Total_Farms",
      "equation": "Conventional_Farms + Transitioning_Farms + Sustainable_Farms",
      "position": {
        "x": 360,
        "y": 80
      }
    },
    {
      "id": "var-transition-period",
      "name": "Transition_Period",
      "equation": "3",
      "position": {
        "x": 520,
